test('session switch resets the status meter (tok/cost/turn)', () async {
  // The tok/cost/turn readout belongs to the CURRENT session: switching
  // to a fresh one must zero it, not keep counting the previous
  // session's usage.
  const usage = Usage(
    input: 10,
    output: 5,
