    input: 10,
    output: 5,
    cacheRead: 0,
    cacheWrite: 0,
    totalTokens: 15,
    cost: UsageCost(input: 0.0006, output: 0.0004, total: 0.001),
  );
  final fake = FakeStreamFunction([textTurn('hi', usage: usage)]);
  final cli = cliFor(fake.call);
