      width: width,
      dim: _style.dim,
      cwd: _env.cwd,
      home: config.homeDir,
    );
    final count = firstIndex > 0
        ? 'last ${messages.length - firstIndex} of ${messages.length}'
        : '${messages.length}';
    io.writeln(_style.dim('─── restored session: $label ($count messages)'));
    for (final entry in entries) {
      for (final line in entry) {
        io.writeln(line);
      }
    }
