      ErrorEvent(
        reason: StopReason.error,
        error: testAssistant(
          stopReason: StopReason.error,
          errorMessage: 'boom',
        ),
      ),
    ],
  ]);
  final cli = cliFor(fake.call);
  final run = cli.run();

  io.sendLine('q');
  await waitForIt(() => fake.calls == 1 && !cli.isBusy);
  io.sendLine('q2');
  await waitForIt(() => fake.calls == 2 && !cli.isBusy);
