  /// F1a) — empty unless the cut actually folded records away.
  String _classicHiddenIndex(
    List<SessionRecord> hidden,
    RecordSeqIndex? seqs,
  ) => seqs == null || hidden.isEmpty ? '' : hiddenIndexSection(hidden, seqs);
}

