    io.sendLine('/exit');
    await run;

    final result = await env.readTextFile('/home/.fah/logs/fa.log');
    final log = result.valueOrNull ?? '';
    expect(log, contains('precious prior line'));
    expect(log, contains('fa boot'));
  });

