      expect(cli.sessionPickerItemsForTest!.first.key, 'tree');
      await cli.tuiPickSessionForTest('tree');
      await cli.openSessionsPickerForTest();
      expect(cli.sessionPickerItemsForTest!.first.key, 'flat');

