    final foreign = await namedSession('widgets', '/other');
    final fake = FakeStreamFunction([textTurn('ok')]);
    final cli = cliFor(fake.call, sessionName: 'widgets');
    final run = cli.run();
    await waitForIt(() => io.out.toString().contains(foreign.id));
    io.sendLine('/exit');
    await run;
  });

