            : [
                UserMessage.text(
                  '$branchSummaryPrefix'
                  '${sanitizeSummary(summary).text}'
                  '$branchSummarySuffix',
                  timestamp: timestamp,
                ),
              ],
      _ => const [],
    };
  }

