/// In-memory [FileSystem] whose session-file opens/appends transiently
/// fail with an ENOENT-shaped [FileError] for the first N calls of a
/// chosen op (issue #427): the fake stands in for hosts where a session
/// file briefly disappears mid-IO (macOS Group Containers materialization,
/// backup, AV scans). Fully deterministic — no real filesystem involved.
final class FlakySessionFs implements FileSystem, RangedReadFileSystem {
  FlakySessionFs([MemoryFileSystem? delegate])
    : _delegate = delegate ?? MemoryFileSystem();

  final MemoryFileSystem _delegate;

  /// How many more [readTextFile]/[fileInfo]/[readRange] calls fail before
  /// reads succeed (the open path's read surface since gh-1073: the open
  /// stats first and streams ranged chunks — it never readTextFiles).
  int failNextReads = 0;

  /// How many more [writeFile] calls fail before writes succeed.
  int failNextWrites = 0;

  /// How many more [appendFile] calls fail before appends succeed.
  int failNextAppends = 0;

  /// How many more [listDir] calls fail before listings succeed.
  int failNextListings = 0;

  /// How many more [fileInfo] calls fail before stats succeed. On top of
  /// [failNextReads], which also covers stats (the open path's read
  /// surface since gh-1073), for tests that target the stat specifically.
  int failNextFileInfos = 0;

  /// When set, [writeFile] calls whose (path, content) match fail with
  /// the same ENOENT-shaped error — stands in for hosts where only one
  /// write shape fails (e.g. a rotation seed that never lands).
  bool Function(String path, String content)? failWritesWhere;

  /// Total calls seen per op, successes and simulated ENOENTs alike —
  /// the retry-cap assertions read these.
  int readCalls = 0;
  int statCalls = 0;
  int rangeCalls = 0;
  int writeCalls = 0;
  int appendCalls = 0;

  static FileError _enoent(String path) => FileError(
