{"path":"test/cli/resumed_context_cache_test.dart","content":"import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

/// The warm-switch context cache (gh-1734 root cause 3): a resumed
/// session whose file is unchanged since the last open/switch reuses the
/// built [SessionContext] instead of re-paying the projection walk.
/// Entries are keyed by (path, size, mtime); every hit hands out a fresh
/// message list so a consumer mutating it can never corrupt the cache.
void main() {
  SessionContext contextOf(String marker) => SessionContext(
    messages: [UserMessage.text(marker)],
    thinkingLevel: 'off',
    model: null,
    activeToolNames: null,
  );

  test('misses on an empty cache', () {
    final cache = ResumedContextCache();
    expect(
      cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 1),
      isNull,
    );
  });

  test('hits on the same path + size + mtime', () {
    final cache = ResumedContextCache()
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 10,
        mtimeMs: 1,
        context: contextOf('a'),
      );
    final hit = cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 1);
    expect(hit, isNotNull);
    expect(hit!.messages.single, isA<UserMessage>());
    expect((hit.messages.single as UserMessage).text, 'a');
  });

  test('misses when the size changes (an append landed)', () {
    final cache = ResumedContextCache()
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 10,
        mtimeMs: 1,
        context: contextOf('a'),
      );
    expect(cache.match('/s/a.jsonl', sizeBytes: 11, mtimeMs: 1), isNull);
  });

  test('misses when the mtime changes', () {
    final cache = ResumedContextCache()
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 10,
        mtimeMs: 1,
        context: contextOf('a'),
      );
    expect(cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 2), isNull);
  });

  test('misses for a different path with identical stats', () {
    final cache = ResumedContextCache()
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 10,
        mtimeMs: 1,
        context: contextOf('a'),
      );
    expect(cache.match('/s/b.jsonl', sizeBytes: 10, mtimeMs: 1), isNull);
  });

  test('re-remembering the same path refreshes the entry', () {
    final cache = ResumedContextCache()
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 10,
        mtimeMs: 1,
        context: contextOf('old'),
      )
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 20,
        mtimeMs: 2,
        context: contextOf('new'),
      );
    expect(cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 1), isNull);
    final hit = cache.match('/s/a.jsonl', sizeBytes: 20, mtimeMs: 2);
    expect((hit!.messages.single as UserMessage).text, 'new');
  });

  test('each hit hands out a fresh message list', () {
    final cache = ResumedContextCache()
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 10,
        mtimeMs: 1,
        context: contextOf('a'),
      );
    cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 1)!.messages.clear();
    final second = cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 1);
    expect(second!.messages, hasLength(1));
  });

  test('evicts the least-recently-used entry beyond the capacity', () {
    final cache = ResumedContextCache(capacity: 2)
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 1,
        mtimeMs: 1,
        context: contextOf('a'),
      )
      ..remember(
        '/s/b.jsonl',
        sizeBytes: 1,
        mtimeMs: 1,
        context: contextOf('b'),
      )
      // A hit on `a` refreshes it — `b` becomes the LRU entry.
      ..match('/s/a.jsonl', sizeBytes: 1, mtimeMs: 1)
      ..remember(
        '/s/c.jsonl',
        sizeBytes: 1,
        mtimeMs: 1,
        context: contextOf('c'),
      );
    expect(
      cache.match('/s/a.jsonl', sizeBytes: 1, mtimeMs: 1),
      isNotNull,
      reason: 'the refreshed entry survives',
    );
    expect(
      cache.match('/s/b.jsonl', sizeBytes: 1, mtimeMs: 1),
      isNull,
      reason: 'the least-recently-used entry was evicted',
    );
    expect(cache.match('/s/c.jsonl', sizeBytes: 1, mtimeMs: 1), isNotNull);
  });

  test('clear() empties the cache', () {
    final cache = ResumedContextCache()
      ..remember(
        '/s/a.jsonl',
        sizeBytes: 10,
        mtimeMs: 1,
        context: contextOf('a'),
      )
      ..clear();
    expect(cache.length, 0);
    expect(cache.match('/s/a.jsonl', sizeBytes: 10, mtimeMs: 1), isNull);
  });
}
"}

{"content":"import 'dart:typed_data';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

/// The `readCustomRecordsOfType` scan memo (gh-1734): the boot/switch
/// path scans the session chain for tail records (obligations ledger,
/// orphan reports, subagent registry, steering) on EVERY open/switch —
/// a 95MB-tail read on a marathon file each time. The repo memoizes the
/// scan result per (path, params, size, mtime): an unchanged file is
/// served from the memo, any append invalidates it.
void main() {
  late CountingEnv env;
  late JsonlSessionRepo repo;
  late Session session;
  late SessionMetadata metadata;

  setUp(() async {
    env = CountingEnv(cwd: '/work');
    repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    session = await repo.create(
      JsonlSessionCreateOptions(cwd: '/work', metadata: {'agent': 'cli'}),
    );
    await session.appendSessionName('scan-memo');
    await session.appendCustomEntry(customType: 'a_type', data: {'n': 1});
    metadata = await session.getMetadata();
    env.readRangeCalls.clear();
  });

  test('an unchanged file is scanned once — the repeat call is memoized',
      () async {
    final first = await repo.readCustomRecordsOfType(metadata, {'a_type'});
    expect(first, hasLength(1));
    final callsAfterFirst = env.readRangeCalls.length;
    expect(callsAfterFirst, greaterThan(0));

    final second = await repo.readCustomRecordsOfType(metadata, {'a_type'});
    expect(second, hasLength(1));
    expect(second.single.id, first.single.id);
    expect(
      env.readRangeCalls.length,
      callsAfterFirst,
      reason: 'the second scan must be served from the memo, not re-read',
    );
  });

  test('an append invalidates the memo — the new record is seen', () async {
    await repo.readCustomRecordsOfType(metadata, {'a_type'});
    final callsAfterFirst = env.readRangeCalls.length;

    await session.appendCustomEntry(customType: 'a_type', data: {'n': 2});
    final freshMetadata = await session.getMetadata();

    final second = await repo.readCustomRecordsOfType(
      freshMetadata,
      {'a_type'},
    );
    expect(second, hasLength(2));
    expect(
      env.readRangeCalls.length,
      greaterThan(callsAfterFirst),
      reason: 'a changed file must be re-scanned',
    );
  });

  test('records of another type are invisible to the memo entry', () async {
    await repo.readCustomRecordsOfType(metadata, {'a_type'});
    final other = await repo.readCustomRecordsOfType(metadata, {'b_type'});
    expect(other, isEmpty);
  });

  test('a multi-type scan memoizes independently of a single-type scan',
      () async {
    await repo.readCustomRecordsOfType(metadata, {'a_type'});
    final callsAfterSingle = env.readRangeCalls.length;
    final both = await repo.readCustomRecordsOfType(metadata, {
      'a_type',
      'b_type',
    });
    expect(both, hasLength(1));
    expect(
      env.readRangeCalls.length,
      greaterThan(callsAfterSingle),
      reason: 'a different type set is a different memo key',
    );
  });

  test('lastSegmentOnly scans are memoized under their own key', () async {
    await repo.readCustomRecordsOfType(metadata, {'a_type'});
    final callsAfterWhole = env.readRangeCalls.length;
    final lastOnly = await repo.readCustomRecordsOfType(
      metadata,
      {'a_type'},
      lastSegmentOnly: true,
    );
    expect(lastOnly, hasLength(1));
    expect(
      env.readRangeCalls.length,
      greaterThan(callsAfterWhole),
      reason: 'a different segment scope is a different memo key',
    );
    // And a repeat of the lastSegmentOnly shape hits ITS memo.
    final callsAfterLastOnly = env.readRangeCalls.length;
    await repo.readCustomRecordsOfType(
      metadata,
      {'a_type'},
      lastSegmentOnly: true,
    );
    expect(env.readRangeCalls.length, callsAfterLastOnly);
  });

  test('a memo hit returns records that decode identically', () async {
    final first = await repo.readCustomRecordsOfType(metadata, {'a_type'});
    final second = await repo.readCustomRecordsOfType(metadata, {'a_type'});
    expect(second.single.customType, first.single.customType);
    expect(second.single.data, first.single.data);
  });
}

/// A [MemoryExecutionEnv] counting ranged reads per path — the streamed
/// custom-record scan is the read path the memo must collapse.
class CountingEnv extends MemoryExecutionEnv {
  CountingEnv({required super.cwd});

  final readRangeCalls = <String>[];

  @override
  Future<Result<Uint8List, FileError>> readRange(
    String path,
    int start,
    int end,
  ) {
    readRangeCalls.add(path);
    return super.readRange(path, start, end);
  }
}
