final class ResumedContextCache {
 ResumedContextCache({int capacity = 4}) : capacity = capacity < 1 ? 1 : capacity;
 final int capacity;
 final _entries = <String, _Entry>{};

 int get length => _entries.length;

 SessionContext? match(String path, {required int sizeBytes, required int mtimeMs}) {
  final entry = _entries[path];
  if (entry == null) return null;
  if (entry.sizeBytes != sizeBytes || entry.mtimeMs != mtimeMs) {
    _entries.remove(path);
    return null;
  }
  // LRU refresh: re-insert at the most-recent position.
  _entries.remove(path);
  _entries[path] = entry;
  return SessionContext(
    messages: List.of(entry.context.messages),
    thinkingLevel: entry.context.thinkingLevel,
    model: entry.context.model,
    activeToolNames: entry.context.activeToolNames == null ? null : List.of(entry.context.activeToolNames!),
  );
 }

 void remember(String path, {required int sizeBytes, required int mtimeMs, required SessionContext context}) {
  if (_entries.containsKey(path)) _entries.remove(path);
  _entries[path] = _Entry(sizeBytes: sizeBytes, mtimeMs: mtimeMs, context: context);
  while (_entries.length > capacity) {
    _entries.remove(_entries.keys.first);
  }

 void clear() => _entries.clear();
}
