  /// when any stat fails (missing/unreadable file): no memo then, the
  /// scan runs and returns whatever it finds (unchanged behavior).
  Future<Map<String, (int, int)>?> _scanChainFingerprint(
    List<String> paths,
    int? tailCapBytes,
  ) async {
    final print = <String, (int, int)>{};
