  /// The context built for [path] when the file still has exactly
  /// ([sizeBytes], [mtimeMs]) and the same build [variant] — a caller
  /// dimension that changes the meaning of a build (the CLI's resume
  /// budget bounds how much history the walk keeps resident, so a
  /// different budget legitimately builds a different slice). The
  /// returned context carries a fresh message list; the entry is
  /// refreshed as the most recently used. A stale probe does not evict
  /// the entry (the caller rebuilds and re-remembers over it).
  SessionContext? match(
    String path, {
    required int sizeBytes,
    required int mtimeMs,
    int variant = 0,
  }) {
    final entry = _entries[path];
    if (entry == null) return null;
    if (entry.sizeBytes != sizeBytes ||
        entry.mtimeMs != mtimeMs ||
        entry.variant != variant) {
      return null;
    }
    _entries.remove(path);
    _entries[path] = entry;
    return SessionContext(
      messages: List.of(entry.context.messages),
      thinkingLevel: entry.context.thinkingLevel,
      model: entry.context.model,
      activeToolNames: entry.context.activeToolNames == null
          ? null
          : List.of(entry.context.activeToolNames!),
    );
  }

  /// Remembers [context] as the build for [path] at the given fingerprint
  /// and [variant].
  void remember(
    String path, {
    required int sizeBytes,
    required int mtimeMs,
    required SessionContext context,
    int variant = 0,
  }) {
    _entries.remove(path);
    _entries[path] = _Entry(
      sizeBytes: sizeBytes,
      mtimeMs: mtimeMs,
      variant: variant,
      context: context,
    );
    while (_entries.length > capacity) {
      _entries.remove(_entries.keys.first);
    }
  }

  /// Drops every entry.
  void clear() => _entries.clear();
}

