/// The warm-switch resumed-context cache (gh-1734 root cause 3): a
/// session whose file is unchanged since its last open reuses the built
/// [SessionContext] instead of re-paying the projection walk on every
/// open/switch. Entries are keyed by (path, sizeBytes, mtimeMs, variant);
/// any change to the file (append, rotation, truncate) produces a
/// different fingerprint and a clean miss; the caller-supplied [variant]
/// separates builds whose meaning changed (the resume budget bounds how
/// much history a build carries).
library;

import '../session/session_tree.dart';

/// One memoized context build with the stat fingerprint it was built at.
final class _Entry {
  _Entry({
    required this.sizeBytes,
    required this.mtimeMs,
    required this.variant,
    required this.context,
  });

  final int sizeBytes;
  final int mtimeMs;
  final int variant;
  final SessionContext context;

  final int sizeBytes;
  final int mtimeMs;
  final SessionContext context;
}

